#include "MosuanUiPanels.h"
#include "MosuanUiState.h"
#include "MosuanUiPrimitives.h"
namespace MosuanUI {
static bool hit(POINT p,RECT r){return PtInRect(&r,p)!=FALSE;}
void drawLayerPanel(HDC dc,const RECT& rc){auto&s=state();if(!s.layersOpen)return;int right=rc.right-kRightRail-18,left=right-kLayerPanelWidth,bottom=rc.bottom-24,top=92;RECT p{left,top,right,bottom};fillRound(dc,p,color(20,26,35),20);strokeRound(dc,p,color(70,80,95),20);text(dc,L"图层",{left+24,top+14,left+120,top+48},20,color(245,248,252));text(dc,L"×",{right-46,top+13,right-18,top+45},25,color(200,210,220),DT_CENTER|DT_VCENTER|DT_SINGLELINE);
const wchar_t* names[]={L"重点标记",L"课前板书",L"课堂演算",L"学生答案",L"PDF",L"背景"};for(int i=0;i<6;i++){int y=top+62+i*58;RECT row{left+12,y,right-12,y+50};if(i==2)fillRound(dc,row,color(47,103,195),10);icon(dc,i<4?6:20,{left+28,y+7,left+56,y+35},i==2);text(dc,names[i],{left+66,y,right-90,y+50},16,color(232,237,244));icon(dc,i<4?22:23,{right-70,y+10,right-40,y+40},i<4);icon(dc,24,{right-38,y+10,right-10,y+40});}
int y=bottom-58;int xs[]={left+16,left+82,left+148,left+214,left+280};int icons[]={24,25,26,23,27};const wchar_t* labels[]={L"新建",L"上移",L"下移",L"锁定",L"删除"};for(int i=0;i<5;i++){RECT b{xs[i],y,xs[i]+52,y+44};fillRound(dc,b,color(30,37,47),10);icon(dc,icons[i],{b.left+12,b.top+5,b.left+40,b.top+33});text(dc,labels[i],{b.left,b.top+25,b.right,b.bottom},11,color(170,180,192),DT_CENTER|DT_VCENTER|DT_SINGLELINE);}}
void drawSettingsPanel(HDC dc,const RECT& rc){auto&s=state();if(!s.settingsOpen)return;int right=rc.right-kRightRail-18,left=right-330,bottom=rc.bottom-24,top=rc.bottom-320;RECT p{left,top,right,bottom};fillRound(dc,p,color(20,26,35),20);strokeRound(dc,p,color(70,80,95),20);text(dc,L"页面设置",{left+22,top+14,left+150,top+46},19,color(245,248,252));text(dc,L"×",{right-44,top+12,right-18,top+42},25,color(200,210,220),DT_CENTER|DT_VCENTER|DT_SINGLELINE);text(dc,L"换页方式",{left+22,top+60,right-20,top+90},14,color(180,190,202));
RECT a{left+22,top+98,left+150,top+164},b{left+162,top+98,right-22,top+164};fillRound(dc,a,s.singlePage?color(55,116,210):color(30,37,47),12);fillRound(dc,b,!s.singlePage?color(55,116,210):color(30,37,47),12);icon(dc,4,{a.left+14,a.top+12,a.left+48,a.top+46},s.singlePage);icon(dc,4,{b.left+14,b.top+12,b.left+48,b.top+46},!s.singlePage);text(dc,L"单页（左右切换）",{a.left+50,a.top+12,a.right-6,a.bottom-10},12,color(235,240,246));text(dc,L"连续（上下滚动）",{b.left+50,b.top+12,b.right-6,b.bottom-10},12,color(235,240,246));
text(dc,L"两侧显示背景",{left+22,top+184,right-90,top+220},14,color(220,226,234));text(dc,s.backgroundVisible?L"●":L"○",{right-62,top+178,right-24,top+224},26,s.backgroundVisible?color(70,140,240):color(130,140,150),DT_CENTER|DT_VCENTER|DT_SINGLELINE);text(dc,L"显示笔记",{left+22,top+232,right-90,top+268},14,color(220,226,234));text(dc,s.notesVisible?L"●":L"○",{right-62,top+226,right-24,top+272},26,s.notesVisible?color(70,140,240):color(130,140,150),DT_CENTER|DT_VCENTER|DT_SINGLELINE);}
bool handlePanelClick(POINT p,const RECT& rc){auto&s=state();if(s.layersOpen){int right=rc.right-kRightRail-18,left=right-kLayerPanelWidth,top=92;if(hit(p,{right-52,top+8,right-10,top+52})){s.layersOpen=false;return true;}}
if(s.settingsOpen){int right=rc.right-kRightRail-18,left=right-330,top=rc.bottom-320;if(hit(p,{right-48,top+8,right-8,top+50})){s.settingsOpen=false;return true;}if(hit(p,{left+22,top+98,left+150,top+164})){s.singlePage=true;return true;}if(hit(p,{left+162,top+98,right-22,top+164})){s.singlePage=false;return true;}if(hit(p,{right-80,top+170,right-15,top+230})){s.backgroundVisible=!s.backgroundVisible;SendMessageW(s.main,WM_BACKGROUND_VISIBILITY,s.backgroundVisible,0);return true;}if(hit(p,{right-80,top+220,right-15,top+280})){s.notesVisible=!s.notesVisible;SendMessageW(s.main,WM_NOTE_VISIBILITY,s.notesVisible,0);return true;}}return false;}
}
